<template>
  <PageTitle title="Conversations" size="sm" />
  <ProjectConversationFilters :params="params" :project-id="projectId" />
  <Card>
    <CardContent class="!p-0 md:!p-0">
      <AppLoader v-if="isLoading" variant="inline" subject="conversations" />
      <AppError
        v-else-if="error"
        title="Failed to load conversations"
        :error="error"
        variant="table"
        :action="refetch"
        action-text="Retry"
      />
      <template v-else>
        <ResponsiveTable rounded>
          <ResponsiveTableHeader>
            <ResponsiveTableHead v-if="isAdminOrManager" class="text-accent-foreground text-xs sm:text-sm leading-6">
              Canvasser</ResponsiveTableHead
            >
            <ResponsiveTableHead class="text-center w-fit text-nowrap">Created At</ResponsiveTableHead>
            <ResponsiveTableHead class="text-center w-fit text-nowrap">Duration</ResponsiveTableHead>
            <ResponsiveTableHead class="text-center w-fit">Status</ResponsiveTableHead>
          </ResponsiveTableHeader>
          <ResponsiveTableBody>
            <ResponsiveTableEmpty
              v-if="(totalCount === 0 || items.length === 0) && !isLoading"
              :colspan="isAdminOrManager ? 4 : 3"
              :cols="3"
              :cols-sm="3"
              cell-class="text-center"
            >
              <AppGuidedEmpty v-if="showGuided && guidedContent" v-bind="guidedContent" variant="table" />
              <AppEmpty v-else subject="conversations" variant="table" />
            </ResponsiveTableEmpty>
            <ResponsiveTableRow
              v-for="item in items"
              v-else
              :key="item.id"
              :to="{ name: 'conversations-id', params: { id: item.id } }"
            >
              <ResponsiveTableCell v-if="isAdminOrManager" :cols="3" :cols-sm="3" label="Canvasser">
                <UserNameWithCompany :user="item.canvasser" />
              </ResponsiveTableCell>
              <ResponsiveTableCell :cols="2" :cols-sm="1" label="Created At">
                <p class="text-base md:text-center">
                  {{ formatDateTzToFormat(item.created_at, 'MM/dd/yyyy, hh:mm aaa', timezone) }}
                </p>
              </ResponsiveTableCell>
              <ResponsiveTableCell :cols="2" :cols-sm="1" label="Duration">
                <p class="text-base md:text-center">
                  <template v-if="item.duration != null">
                    {{ formatSecondsDuration(item.duration) }}
                  </template>
                  <span v-else class="text-muted-foreground">N/A</span>
                </p>
              </ResponsiveTableCell>
              <ResponsiveTableCell :cols="2" :cols-sm="1" label="Status">
                <div class="flex md:justify-center">
                  <Badge :variant="getConversationStatusBadge(item.status).variant">
                    {{ getConversationStatusBadge(item.status).label }}
                  </Badge>
                </div>
              </ResponsiveTableCell>
            </ResponsiveTableRow>
          </ResponsiveTableBody>
          <ResponsiveTableFooter
            v-if="totalCount > 0 && items.length > 0"
            :colspan="isAdminOrManager ? 4 : 3"
            :cols="4"
            :cols-sm="4"
          >
            <AppPagination :page="params.page" :size="params.size" :total="totalCount" label="conversations" />
          </ResponsiveTableFooter>
        </ResponsiveTable>
      </template>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import {
  getConversationList,
  type ProjectShortInfo,
  type ProjectEditTabsStatusResponse,
  type SortType,
  type ConversationSortBy,
  type ConversationStatus,
} from '~/client';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';
import { getConversationStatusBadge } from '~/constants/conversations/conversationStatuses';
import {
  projectConversationsGuidedEmpty,
  PROJECT_CONVERSATIONS_FILTER_DEFAULTS,
} from '~/constants/guidedEmpty/projectConversations';

definePageMeta({
  backGroup: 'project-details',
  backLabel: 'project',
});

interface Props {
  projectId: string;
  projectShortInfo?: ProjectShortInfo;
  tabStatus?: ProjectEditTabsStatusResponse;
}

const props = defineProps<Props>();

const { timezone, isAdminOrManager } = useUserRole();

const route = useRoute();
const router = useRouter();

onMounted(() => {
  if (route.query.statuses === undefined) {
    router.replace({ query: { ...route.query, statuses: 'completed' } });
  }
});

const params = computed(() => {
  const route = useRoute();
  const { subcontractor_company_ids, include_unassigned } = parseSubcontractorCompanyFilter(
    route.query.subcontractor_company_ids
  );
  const urlParams = {
    ...parsePagination(route.query),
    sort_by: (route.query.sort_by as ConversationSortBy) || 'created_at',
    sort_type: isSortType(route.query.sort_type as string) ? (route.query.sort_type as SortType) : 'desc',
    statuses: processArrayQueryParameterFromUrl<ConversationStatus>(route.query.statuses),
    canvasser_ids: processArrayQueryParameterFromUrl(route.query.canvasser_ids),
    search_query: (route.query.search_query as string) || undefined,
    duration_min: route.query.duration_min ? Number(route.query.duration_min) : undefined,
    duration_max: route.query.duration_max ? Number(route.query.duration_max) : undefined,
    subcontractor_company_ids,
    include_unassigned,
  };

  return Object.fromEntries(Object.entries(urlParams).filter(([_, value]) => value !== undefined)) as typeof urlParams;
});

const {
  data: conversationData,
  error,
  isLoading,
  refetch,
} = useQuery({
  key: () => ['project-conversations', props.projectId, params.value],
  query: () =>
    getConversationList({
      composable: '$fetch',
      query: {
        ...params.value,
        project_ids: [props.projectId],
      },
    }),
  enabled: () => !!props.projectId,
  staleTime: 0,
});

const items = computed(() => conversationData.value?.items ?? []);
const totalCount = computed(() => conversationData.value?.total_count ?? 0);

const isEmpty = computed(() => totalCount.value === 0 || items.value.length === 0);
const { guidedContent, showGuided } = useGuidedEmpty(
  projectConversationsGuidedEmpty,
  isEmpty,
  PROJECT_CONVERSATIONS_FILTER_DEFAULTS
);
</script>
